import{p as e}from"./index-CDrbvjO1.js";var t={id:`derivatives`,courseId:`calculus-1`,courseTitle:`Calculus I`,title:`Derivatives`,concepts:[{id:`power-rule`,title:`Power rule`,objective:`Differentiate powers of x, including roots and reciprocals rewritten as powers.`,prerequisites:[],source:{title:`OpenStax Calculus Volume 1`,section:`3.3 Differentiation Rules`,url:`https://openstax.org/books/calculus-volume-1/pages/3-3-differentiation-rules`},status:`unverified`,explanation:[`For a constant exponent $n$, the derivative of $x^n$ is $nx^{n-1}$. Bring the exponent down in front as a coefficient, then lower the exponent by one.`,`Roots and fractions follow the same rule once they are written as powers. For example, $\\sqrt{x} = x^{1/2}$ and $\\frac{1}{x^2} = x^{-2}$.`],takeaways:[`$\\frac{d}{dx}x^n = nx^{n-1}$`,`Rewrite roots and fractions as powers of $x$ before differentiating.`,`The derivative of $x$ is $1$, because $x = x^1$ and $1 \\cdot x^0 = 1$.`],example:{problem:`Find $f'(x)$ for $f(x) = \\sqrt{x}$.`,steps:[`Rewrite the root as a power: $f(x) = x^{1/2}$.`,`Apply the power rule: $f'(x) = \\frac{1}{2}x^{1/2 - 1} = \\frac{1}{2}x^{-1/2}$.`,`Rewrite without a negative exponent: $f'(x) = \\frac{1}{2\\sqrt{x}}$.`]},questions:[{id:`power-rule-1`,level:1,kind:`expression`,status:`unverified`,prompt:`Find $f'(x)$ for $f(x) = x^5$.`,answer:`5x^4`,derivativeOf:`x^5`,hint:`Bring the exponent down as a coefficient, then subtract one from the exponent.`,solution:`$\\frac{d}{dx}x^5 = 5x^{5-1} = 5x^4$.`,mistakes:[{answer:`5x^5`,tag:`power-rule-kept-exponent`,feedback:`You brought the 5 down but left the exponent at 5. Lower it by one: $x^5$ becomes $5x^4$.`},{answer:`x^4`,tag:`power-rule-forgot-coefficient`,feedback:`The exponent dropped correctly, but the old exponent, 5, also comes down in front as a coefficient.`},{answer:`5x^6`,tag:`power-rule-raised-exponent`,feedback:`The exponent goes down by one, not up. Raising the exponent is what happens when integrating.`}]},{id:`power-rule-2`,level:1,kind:`multiple-choice`,status:`unverified`,prompt:`What is the derivative of $x^8$?`,solution:`The 8 comes down and the exponent drops to 7: $8x^7$.`,options:[{text:`$8x^7$`,correct:!0},{text:`$7x^8$`,tag:`power-rule-swapped-numbers`,feedback:`The coefficient is the original exponent, 8, and the new exponent is one less, 7.`},{text:`$8x^9$`,tag:`power-rule-raised-exponent`,feedback:`The exponent goes down by one, not up.`},{text:`$x^7$`,tag:`power-rule-forgot-coefficient`,feedback:`The exponent dropped correctly, but the 8 must also come down in front.`}]},{id:`power-rule-3`,level:1,kind:`expression`,status:`unverified`,prompt:`Find $f'(x)$ for $f(x) = x$.`,answer:`1`,derivativeOf:`x`,hint:`Write $x$ as a power of $x$ first.`,solution:`$x = x^1$, so $f'(x) = 1 \\cdot x^0 = 1$. The graph of $y = x$ has slope 1 everywhere.`,mistakes:[{answer:`0`,tag:`power-rule-x-treated-as-constant`,feedback:`$x$ is not a constant. It is $x^1$, so its derivative is $1 \\cdot x^0 = 1$.`},{answer:`x`,tag:`power-rule-forgot-to-differentiate`,feedback:`That is the original function. Apply the power rule to $x^1$.`}]},{id:`power-rule-4`,level:2,kind:`expression`,status:`unverified`,prompt:`Find $f'(x)$ for $f(x) = \\sqrt[3]{x}$. Fractional and negative exponents are fine, for example x^(-1/2).`,answer:`(1/3)x^(-2/3)`,derivativeOf:`x^(1/3)`,hint:`Rewrite the cube root as $x^{1/3}$, then use the power rule.`,solution:`$\\sqrt[3]{x} = x^{1/3}$, so $f'(x) = \\frac{1}{3}x^{1/3 - 1} = \\frac{1}{3}x^{-2/3}$.`,mistakes:[{answer:`(1/3)x^(2/3)`,tag:`power-rule-fraction-subtraction`,feedback:`Check the new exponent: $\\frac{1}{3} - 1 = -\\frac{2}{3}$, not $\\frac{2}{3}$.`},{answer:`(1/3)x^(-1/3)`,tag:`power-rule-fraction-subtraction`,feedback:`Check the new exponent: $\\frac{1}{3} - 1 = -\\frac{2}{3}$.`}]},{id:`power-rule-5`,level:2,kind:`expression`,status:`unverified`,prompt:`Find $f'(x)$ for $f(x) = \\frac{1}{x^3}$.`,answer:`-3x^(-4)`,derivativeOf:`1/x^3`,hint:`Rewrite $\\frac{1}{x^3}$ as $x^{-3}$ first.`,solution:`$\\frac{1}{x^3} = x^{-3}$, so $f'(x) = -3x^{-3-1} = -3x^{-4}$, which is $-\\frac{3}{x^4}$.`,mistakes:[{answer:`-3x^(-2)`,tag:`power-rule-negative-exponent-subtraction`,feedback:`With a negative exponent, subtracting one makes it more negative: $-3 - 1 = -4$.`},{answer:`3x^(-4)`,tag:`power-rule-dropped-negative`,feedback:`The exponent $-3$ comes down as the coefficient, so the result is negative.`},{answer:`1/(3x^2)`,tag:`power-rule-differentiated-denominator`,feedback:`You cannot differentiate the denominator by itself. Rewrite $\\frac{1}{x^3}$ as $x^{-3}$, then use the power rule.`}]},{id:`power-rule-6`,level:3,kind:`multiple-choice`,status:`unverified`,prompt:`Why can't the power rule be used on $2^x$?`,solution:`The power rule is for a variable base raised to a constant exponent, $x^n$. In $2^x$ the variable is in the exponent, so it needs the rule for exponential functions, covered in Section 3.9.`,options:[{text:`The variable is in the exponent. The power rule needs a variable base with a constant exponent, $x^n$.`,correct:!0},{text:`It can be used: the derivative is $x \\cdot 2^{x-1}$.`,tag:`power-rule-applied-to-exponential`,feedback:`That applies the power rule where it does not fit. The derivative of $2^x$ is $2^x \\ln 2$, from Section 3.9.`},{text:`It can be used after rewriting $2^x$ as $x^2$.`,tag:`power-rule-applied-to-exponential`,feedback:`$2^x$ and $x^2$ are different functions. At $x = 3$ they equal 8 and 9.`}]}]},{id:`sum-and-constant-rules`,title:`Constants, sums and constant multiples`,objective:`Differentiate polynomials term by term using the constant, constant multiple and sum rules.`,prerequisites:[`power-rule`],source:{title:`OpenStax Calculus Volume 1`,section:`3.3 Differentiation Rules`,url:`https://openstax.org/books/calculus-volume-1/pages/3-3-differentiation-rules`},status:`unverified`,explanation:[`The derivative of a constant is 0, because a constant function has a flat graph with slope 0 everywhere.`,`A constant factor stays in front: $\\frac{d}{dx}[k f(x)] = k f'(x)$. Sums and differences are differentiated term by term: $\\frac{d}{dx}[f(x) \\pm g(x)] = f'(x) \\pm g'(x)$.`,`Together with the power rule, these rules differentiate any polynomial.`],takeaways:[`$\\frac{d}{dx}c = 0$ for any constant $c$.`,`$\\frac{d}{dx}[k f(x)] = k f'(x)$`,`Differentiate a sum or difference one term at a time.`],example:{problem:`Find $f'(x)$ for $f(x) = 4x^3 - 5x^2 + 7x - 2$.`,steps:[`Differentiate each term: $\\frac{d}{dx}4x^3 = 12x^2$, $\\frac{d}{dx}(-5x^2) = -10x$, $\\frac{d}{dx}7x = 7$ and $\\frac{d}{dx}(-2) = 0$.`,`Combine the results: $f'(x) = 12x^2 - 10x + 7$.`]},questions:[{id:`sum-and-constant-rules-1`,level:1,kind:`expression`,status:`unverified`,prompt:`Find $f'(x)$ for $f(x) = 7$.`,answer:`0`,derivativeOf:`7`,hint:`What is the slope of a horizontal line?`,solution:`A constant never changes, so its derivative is 0.`,mistakes:[{answer:`7`,tag:`constant-derivative-nonzero`,feedback:`A constant does not change, so its rate of change is 0.`},{answer:`1`,tag:`constant-derivative-nonzero`,feedback:`A constant does not change, so its rate of change is 0. The derivative of $x$ is 1, but 7 has no $x$.`}]},{id:`sum-and-constant-rules-2`,level:1,kind:`expression`,status:`unverified`,prompt:`Find $f'(x)$ for $f(x) = 6x^4$.`,answer:`24x^3`,derivativeOf:`6x^4`,hint:`Keep the 6 in front and differentiate $x^4$.`,solution:`$f'(x) = 6 \\cdot 4x^3 = 24x^3$.`,mistakes:[{answer:`4x^3`,tag:`dropped-constant-multiple`,feedback:`The constant 6 stays as a factor: $6 \\cdot 4x^3 = 24x^3$.`},{answer:`24x^4`,tag:`power-rule-kept-exponent`,feedback:`The coefficient is right, but the exponent should drop from 4 to 3.`}]},{id:`sum-and-constant-rules-3`,level:1,kind:`expression`,status:`unverified`,prompt:`Find $f'(x)$ for $f(x) = x^3 + x^2$.`,answer:`3x^2 + 2x`,derivativeOf:`x^3 + x^2`,hint:`Differentiate each term separately and add the results.`,solution:`$\\frac{d}{dx}x^3 + \\frac{d}{dx}x^2 = 3x^2 + 2x$.`,mistakes:[{answer:`6x^3`,tag:`sum-rule-multiplied-terms`,feedback:`The derivatives of the two terms are added, not multiplied: $3x^2 + 2x$.`}]},{id:`sum-and-constant-rules-4`,level:2,kind:`expression`,status:`unverified`,prompt:`Find $f'(x)$ for $f(x) = 2x^5 - 3x^2 + x - 8$.`,answer:`10x^4 - 6x + 1`,derivativeOf:`2x^5 - 3x^2 + x - 8`,hint:`Work term by term. Watch the $x$ term and the constant.`,solution:`Term by term: $10x^4 - 6x + 1 - 0 = 10x^4 - 6x + 1$.`,mistakes:[{answer:`10x^4 - 6x - 7`,tag:`constant-derivative-nonzero`,feedback:`The derivative of the constant $-8$ is 0, so it drops out instead of combining with the 1.`},{answer:`10x^4 - 6x`,tag:`power-rule-x-treated-as-constant`,feedback:`The derivative of $x$ is 1, not 0.`}]},{id:`sum-and-constant-rules-5`,level:2,kind:`numeric`,status:`unverified`,prompt:`For $f(x) = 3x^2 - 4x + 1$, find $f'(2)$.`,answer:8,derivativeOf:`3x^2 - 4x + 1`,at:2,hint:`Find $f'(x)$ first, then substitute $x = 2$.`,solution:`$f'(x) = 6x - 4$, so $f'(2) = 12 - 4 = 8$.`,mistakes:[{answer:5,tag:`evaluated-function-not-derivative`,feedback:`5 is $f(2)$, the value of the function. Differentiate first, then substitute $x = 2$.`},{answer:6,tag:`constant-derivative-nonzero`,feedback:`Check the constant term: the derivative of 1 is 0, so $f'(x) = 6x - 4$.`}]},{id:`sum-and-constant-rules-6`,level:3,kind:`multiple-choice`,status:`unverified`,prompt:`If $g(x) = f(x) + 10$, how do $f'(x)$ and $g'(x)$ compare?`,solution:`Adding 10 shifts the graph up without changing its steepness anywhere, and the derivative of the constant 10 is 0. So $g'(x) = f'(x)$.`,options:[{text:`They are equal, because adding a constant does not change any slopes.`,correct:!0},{text:`$g'(x) = f'(x) + 10$`,tag:`constant-derivative-nonzero`,feedback:`Shifting a graph up moves every point by 10 but keeps every slope the same. The derivative of 10 is 0.`},{text:`$g'(x) = 10 f'(x)$`,tag:`confused-sum-with-multiple`,feedback:`Multiplying by 10 would scale the slopes, but here 10 is added, not multiplied.`}]}]},{id:`product-rule`,title:`Product rule`,objective:`Differentiate a product of two functions with the product rule.`,prerequisites:[`sum-and-constant-rules`],source:{title:`OpenStax Calculus Volume 1`,section:`3.3 Differentiation Rules`,url:`https://openstax.org/books/calculus-volume-1/pages/3-3-differentiation-rules`},status:`unverified`,explanation:[`The derivative of a product is not the product of the derivatives. Instead, $\\frac{d}{dx}[f(x)g(x)] = f'(x)g(x) + f(x)g'(x)$.`,`In words: the derivative of the first times the second, plus the first times the derivative of the second.`],takeaways:[`$(fg)' = f'g + fg'$`,`$(fg)'$ is usually not equal to $f'g'$.`,`Expanding the product first and using the power rule gives the same answer, which is a useful check.`],example:{problem:`Find $h'(x)$ for $h(x) = (x^2 + 1)(x^3 - 2x)$.`,steps:[`Let $f(x) = x^2 + 1$ and $g(x) = x^3 - 2x$. Then $f'(x) = 2x$ and $g'(x) = 3x^2 - 2$.`,`Apply the rule: $h'(x) = 2x(x^3 - 2x) + (x^2 + 1)(3x^2 - 2)$.`,`Simplify: $h'(x) = 5x^4 - 3x^2 - 2$.`,`Check by expanding: $h(x) = x^5 - x^3 - 2x$, so $h'(x) = 5x^4 - 3x^2 - 2$.`]},questions:[{id:`product-rule-1`,level:1,kind:`multiple-choice`,status:`unverified`,prompt:`Which formula is the product rule for $\\frac{d}{dx}[f(x)g(x)]$?`,solution:`$(fg)' = f'g + fg'$: two terms, added.`,options:[{text:`$f'(x)g(x) + f(x)g'(x)$`,correct:!0},{text:`$f'(x)g'(x)$`,tag:`product-of-derivatives`,feedback:`Multiplying the derivatives is the most common product rule mistake. Test it with $f = g = x$: $x^2$ has derivative $2x$, but $f'g' = 1$.`},{text:`$f'(x)g(x) - f(x)g'(x)$`,tag:`confused-product-and-quotient`,feedback:`The minus sign belongs to the quotient rule. The product rule adds the two terms.`}]},{id:`product-rule-2`,level:1,kind:`expression`,status:`unverified`,prompt:`Use the product rule to find $h'(x)$ for $h(x) = x^2(x + 3)$.`,answer:`3x^2 + 6x`,derivativeOf:`x^2 (x + 3)`,hint:`Let $f(x) = x^2$ and $g(x) = x + 3$. Then $h' = f'g + fg'$.`,solution:`$h'(x) = 2x(x + 3) + x^2(1) = 3x^2 + 6x$.`,mistakes:[{answer:`2x`,tag:`product-of-derivatives`,feedback:`You multiplied the derivatives, $(2x)(1)$. The product rule adds two terms: $f'g + fg'$.`}]},{id:`product-rule-3`,level:1,kind:`expression`,status:`unverified`,prompt:`Use the product rule to find $h'(x)$ for $h(x) = (x + 1)(x - 1)$.`,answer:`2x`,derivativeOf:`(x + 1)(x - 1)`,hint:`Both factors have derivative 1.`,solution:`$h'(x) = 1 \\cdot (x - 1) + (x + 1) \\cdot 1 = 2x$. Check: $h(x) = x^2 - 1$, so $h'(x) = 2x$.`,mistakes:[{answer:`1`,tag:`product-of-derivatives`,feedback:`You multiplied the derivatives, $1 \\cdot 1$. The product rule adds two terms: $f'g + fg'$.`}]},{id:`product-rule-4`,level:2,kind:`expression`,status:`unverified`,prompt:`Find $h'(x)$ for $h(x) = (2x^3 + 1)(x^2 - 4)$.`,answer:`10x^4 - 24x^2 + 2x`,derivativeOf:`(2x^3 + 1)(x^2 - 4)`,hint:`$f(x) = 2x^3 + 1$ and $g(x) = x^2 - 4$. Find $f'$ and $g'$, then use $f'g + fg'$.`,solution:`$h'(x) = 6x^2(x^2 - 4) + (2x^3 + 1)(2x) = 10x^4 - 24x^2 + 2x$. Leaving it unsimplified is also accepted.`,mistakes:[{answer:`12x^3`,tag:`product-of-derivatives`,feedback:`You multiplied the derivatives, $(6x^2)(2x)$. The product rule adds two terms: $f'g + fg'$.`},{answer:`6x^2 (x^2 - 4) - (2x^3 + 1)(2x)`,tag:`confused-product-and-quotient`,feedback:`The product rule adds the two terms. The minus sign belongs to the quotient rule.`}]},{id:`product-rule-5`,level:2,kind:`numeric`,status:`unverified`,prompt:`For $h(x) = x^3(2x - 5)$, find $h'(1)$.`,answer:-7,derivativeOf:`x^3 (2x - 5)`,at:1,hint:`Find $h'(x)$ with the product rule, then substitute $x = 1$.`,solution:`$h'(x) = 3x^2(2x - 5) + x^3 \\cdot 2$, so $h'(1) = 3(-3) + 2 = -7$.`,mistakes:[{answer:6,tag:`product-of-derivatives`,feedback:`That is $f'(1)g'(1) = 3 \\cdot 2$. The product rule adds two terms: $f'g + fg'$.`},{answer:-3,tag:`evaluated-function-not-derivative`,feedback:`$-3$ is $h(1)$, the value of the function. Differentiate first, then substitute.`}]},{id:`product-rule-6`,level:3,kind:`numeric`,status:`unverified`,prompt:`Suppose $f(2) = 3$, $f'(2) = -1$, $g(2) = 4$ and $g'(2) = 5$. What is the derivative of $f(x)g(x)$ at $x = 2$?`,answer:11,hint:`Substitute the given values into $f'g + fg'$.`,solution:`$f'(2)g(2) + f(2)g'(2) = (-1)(4) + (3)(5) = 11$.`,mistakes:[{answer:-5,tag:`product-of-derivatives`,feedback:`That is $f'(2)g'(2)$. The product rule is $f'g + fg'$.`},{answer:12,tag:`evaluated-function-not-derivative`,feedback:`12 is $f(2)g(2)$, the value of the product. The question asks for its derivative.`},{answer:-19,tag:`confused-product-and-quotient`,feedback:`That is $f'g - fg'$. The product rule adds the two terms.`}]}]},{id:`quotient-rule`,title:`Quotient rule`,objective:`Differentiate a quotient of two functions with the quotient rule.`,prerequisites:[`product-rule`],source:{title:`OpenStax Calculus Volume 1`,section:`3.3 Differentiation Rules`,url:`https://openstax.org/books/calculus-volume-1/pages/3-3-differentiation-rules`},status:`unverified`,explanation:[`For a quotient where $g(x) \\neq 0$: $\\frac{d}{dx}\\left[\\frac{f(x)}{g(x)}\\right] = \\frac{f'(x)g(x) - f(x)g'(x)}{[g(x)]^2}$.`,`Order matters in the numerator because of the minus sign. Start with the derivative of the top. Swapping the two terms flips the sign of the answer.`],takeaways:[`$\\left(\\frac{f}{g}\\right)' = \\frac{f'g - fg'}{g^2}$`,`The numerator starts with $f'g$, the derivative of the top.`,`If a fraction simplifies first, simplifying can avoid the quotient rule entirely.`],example:{problem:`Find $h'(x)$ for $h(x) = \\frac{x^2}{x + 1}$.`,steps:[`Let $f(x) = x^2$ and $g(x) = x + 1$. Then $f'(x) = 2x$ and $g'(x) = 1$.`,`Apply the rule: $h'(x) = \\frac{2x(x + 1) - x^2 \\cdot 1}{(x + 1)^2}$.`,`Simplify the numerator: $h'(x) = \\frac{x^2 + 2x}{(x + 1)^2}$.`]},questions:[{id:`quotient-rule-1`,level:1,kind:`multiple-choice`,status:`unverified`,prompt:`Which formula is the quotient rule for $\\frac{d}{dx}\\left[\\frac{f(x)}{g(x)}\\right]$?`,solution:`$\\left(\\frac{f}{g}\\right)' = \\frac{f'g - fg'}{g^2}$.`,options:[{text:`$\\frac{f'g - fg'}{g^2}$`,correct:!0},{text:`$\\frac{fg' - f'g}{g^2}$`,tag:`quotient-rule-numerator-order`,feedback:`The numerator terms are in the wrong order, which flips the sign of the result. Start with $f'g$.`},{text:`$\\frac{f'}{g'}$`,tag:`quotient-of-derivatives`,feedback:`Dividing the derivatives does not give the derivative of the quotient.`},{text:`$\\frac{f'g - fg'}{g}$`,tag:`quotient-rule-denominator-not-squared`,feedback:`The numerator is right, but the denominator is squared: $g^2$.`}]},{id:`quotient-rule-2`,level:1,kind:`expression`,status:`unverified`,prompt:`Use the quotient rule to find $h'(x)$ for $h(x) = \\frac{1}{x + 2}$.`,answer:`-1/(x + 2)^2`,derivativeOf:`1/(x + 2)`,hint:`The top is $f(x) = 1$, so $f'(x) = 0$.`,solution:`$h'(x) = \\frac{0 \\cdot (x + 2) - 1 \\cdot 1}{(x + 2)^2} = -\\frac{1}{(x + 2)^2}$.`,mistakes:[{answer:`1/(x + 2)^2`,tag:`quotient-rule-numerator-order`,feedback:`Check the sign. The numerator is $f'g - fg' = 0 \\cdot (x + 2) - 1 \\cdot 1 = -1$.`},{answer:`0`,tag:`quotient-of-derivatives`,feedback:`That is $\\frac{f'}{g'} = \\frac{0}{1}$. Dividing the derivatives does not work; use $\\frac{f'g - fg'}{g^2}$.`}]},{id:`quotient-rule-3`,level:1,kind:`expression`,status:`unverified`,prompt:`Find $h'(x)$ for $h(x) = \\frac{x}{x + 1}$.`,answer:`1/(x + 1)^2`,derivativeOf:`x/(x + 1)`,hint:`$f(x) = x$ and $g(x) = x + 1$, and both have derivative 1.`,solution:`$h'(x) = \\frac{1 \\cdot (x + 1) - x \\cdot 1}{(x + 1)^2} = \\frac{1}{(x + 1)^2}$.`,mistakes:[{answer:`-1/(x + 1)^2`,tag:`quotient-rule-numerator-order`,feedback:`The sign is flipped. The numerator starts with $f'g$: $1 \\cdot (x + 1) - x \\cdot 1 = 1$.`},{answer:`1`,tag:`quotient-of-derivatives`,feedback:`That is $\\frac{f'}{g'} = \\frac{1}{1}$. Use $\\frac{f'g - fg'}{g^2}$ instead.`}]},{id:`quotient-rule-4`,level:2,kind:`expression`,status:`unverified`,prompt:`Find $h'(x)$ for $h(x) = \\frac{x^2 + 1}{x - 3}$.`,answer:`(x^2 - 6x - 1)/(x - 3)^2`,derivativeOf:`(x^2 + 1)/(x - 3)`,hint:`$f(x) = x^2 + 1$ and $g(x) = x - 3$. You do not need to simplify.`,solution:`$h'(x) = \\frac{2x(x - 3) - (x^2 + 1)}{(x - 3)^2} = \\frac{x^2 - 6x - 1}{(x - 3)^2}$.`,mistakes:[{answer:`((x^2 + 1) - 2x(x - 3))/(x - 3)^2`,tag:`quotient-rule-numerator-order`,feedback:`The numerator terms are swapped, which flips the sign. Start with $f'g = 2x(x - 3)$.`},{answer:`2x`,tag:`quotient-of-derivatives`,feedback:`That is $\\frac{f'}{g'} = \\frac{2x}{1}$. Use $\\frac{f'g - fg'}{g^2}$ instead.`},{answer:`(2x(x - 3) - (x^2 + 1))/(x - 3)`,tag:`quotient-rule-denominator-not-squared`,feedback:`The numerator is right, but the denominator should be squared: $(x - 3)^2$.`}]},{id:`quotient-rule-5`,level:2,kind:`numeric`,status:`unverified`,prompt:`For $h(x) = \\frac{2x}{x^2 + 1}$, find $h'(2)$. A fraction such as -3/4 or a decimal is fine.`,answer:-.24,derivativeOf:`2x/(x^2 + 1)`,at:2,hint:`Find $h'(x)$ with the quotient rule, then substitute $x = 2$.`,solution:`$h'(x) = \\frac{2(x^2 + 1) - 2x \\cdot 2x}{(x^2 + 1)^2} = \\frac{2 - 2x^2}{(x^2 + 1)^2}$, so $h'(2) = \\frac{-6}{25} = -0.24$.`,mistakes:[{answer:.24,tag:`quotient-rule-numerator-order`,feedback:`The sign is flipped. The numerator starts with $f'g$, the derivative of the top times the bottom.`},{answer:.5,tag:`quotient-of-derivatives`,feedback:`That is $\\frac{f'(2)}{g'(2)} = \\frac{2}{4}$. Use $\\frac{f'g - fg'}{g^2}$ instead.`},{answer:.8,tag:`evaluated-function-not-derivative`,feedback:`0.8 is $h(2)$, the value of the function. Differentiate first, then substitute.`}]},{id:`quotient-rule-6`,level:3,kind:`multiple-choice`,status:`unverified`,prompt:`You need the derivative of $\\frac{x^3}{x}$ for $x \\neq 0$. What is the most efficient approach?`,solution:`$\\frac{x^3}{x} = x^2$ for $x \\neq 0$, so the derivative is $2x$. The quotient rule gives the same answer with more work.`,options:[{text:`Simplify to $x^2$ first, then use the power rule to get $2x$.`,correct:!0},{text:`Divide the derivatives: $\\frac{3x^2}{1} = 3x^2$.`,tag:`quotient-of-derivatives`,feedback:`Dividing derivatives is not valid, and $3x^2$ does not match the correct derivative, $2x$.`},{text:`There is no shortcut. Every fraction requires the quotient rule.`,tag:`missed-simplification`,feedback:`Any valid method gives the same derivative. Simplifying first often saves work and avoids sign mistakes.`}]}]},{id:`chain-rule`,title:`Chain rule`,objective:`Differentiate a composition of functions, such as a power of a polynomial, with the chain rule.`,prerequisites:[`power-rule`],source:{title:`OpenStax Calculus Volume 1`,section:`3.6 The Chain Rule`,url:`https://openstax.org/books/calculus-volume-1/pages/3-6-the-chain-rule`},status:`unverified`,explanation:[`A composition $f(g(x))$ has an outer function $f$ and an inner function $g$. Its derivative is $f'(g(x)) \\cdot g'(x)$.`,`Differentiate the outer function and leave the inner function unchanged inside it, then multiply by the derivative of the inner function.`,`For powers this becomes $\\frac{d}{dx}[g(x)]^n = n[g(x)]^{n-1} \\cdot g'(x)$.`],takeaways:[`$\\frac{d}{dx}f(g(x)) = f'(g(x)) \\cdot g'(x)$`,`Keep the inner function unchanged in the outer derivative.`,`Do not forget to multiply by the derivative of the inner function.`],example:{problem:`Find $h'(x)$ for $h(x) = (3x^2 + 1)^4$.`,steps:[`The outer function is $u^4$ and the inner function is $u = 3x^2 + 1$.`,`Differentiate the outer function and keep the inside: $4(3x^2 + 1)^3$.`,`Multiply by the derivative of the inside, $6x$: $h'(x) = 4(3x^2 + 1)^3 \\cdot 6x = 24x(3x^2 + 1)^3$.`]},questions:[{id:`chain-rule-1`,level:1,kind:`multiple-choice`,status:`unverified`,prompt:`In $h(x) = (5x - 2)^3$, what is the inner function?`,solution:`The inner function is what is computed first and plugged into the outer function: $5x - 2$.`,options:[{text:`$5x - 2$`,correct:!0},{text:`$u^3$`,tag:`chain-rule-swapped-inner-outer`,feedback:`That is the outer function, the step done last. The inner function goes inside it.`},{text:`$5x$`,tag:`chain-rule-partial-inner`,feedback:`The inner function is everything inside the parentheses, including the $-2$.`}]},{id:`chain-rule-2`,level:1,kind:`expression`,status:`unverified`,prompt:`Find $h'(x)$ for $h(x) = (2x + 1)^3$.`,answer:`6(2x + 1)^2`,derivativeOf:`(2x + 1)^3`,hint:`Differentiate the cube, keep $2x + 1$ inside, then multiply by the derivative of $2x + 1$.`,solution:`$h'(x) = 3(2x + 1)^2 \\cdot 2 = 6(2x + 1)^2$.`,mistakes:[{answer:`3(2x + 1)^2`,tag:`chain-rule-forgot-inner-derivative`,feedback:`You differentiated the outer power but did not multiply by the derivative of the inner function, $2x + 1$, which is 2.`}]},{id:`chain-rule-3`,level:1,kind:`expression`,status:`unverified`,prompt:`Find $h'(x)$ for $h(x) = (x^2 + 1)^2$.`,answer:`4x(x^2 + 1)`,derivativeOf:`(x^2 + 1)^2`,hint:`The outer function is $u^2$ and the inner function is $x^2 + 1$.`,solution:`$h'(x) = 2(x^2 + 1) \\cdot 2x = 4x(x^2 + 1)$.`,mistakes:[{answer:`2(x^2 + 1)`,tag:`chain-rule-forgot-inner-derivative`,feedback:`Multiply by the derivative of the inner function, $2x$.`},{answer:`4x`,tag:`chain-rule-replaced-inner`,feedback:`You replaced the inside with its derivative. Keep $x^2 + 1$ unchanged in the outer derivative, then multiply by $2x$.`}]},{id:`chain-rule-4`,level:2,kind:`expression`,status:`unverified`,prompt:`Find $h'(x)$ for $h(x) = \\sqrt{x^2 + 4}$.`,answer:`x/sqrt(x^2 + 4)`,derivativeOf:`sqrt(x^2 + 4)`,hint:`Write $h(x) = (x^2 + 4)^{1/2}$.`,solution:`$h'(x) = \\frac{1}{2}(x^2 + 4)^{-1/2} \\cdot 2x = \\frac{x}{\\sqrt{x^2 + 4}}$.`,mistakes:[{answer:`1/(2sqrt(x^2 + 4))`,tag:`chain-rule-forgot-inner-derivative`,feedback:`Multiply by the derivative of the inner function, $x^2 + 4$, which is $2x$.`}]},{id:`chain-rule-5`,level:2,kind:`numeric`,status:`unverified`,prompt:`For $h(x) = (x^3 - 2)^2$, find $h'(1)$.`,answer:-6,derivativeOf:`(x^3 - 2)^2`,at:1,hint:`Find $h'(x)$ with the chain rule, then substitute $x = 1$.`,solution:`$h'(x) = 2(x^3 - 2) \\cdot 3x^2$, so $h'(1) = 2(-1)(3) = -6$.`,mistakes:[{answer:-2,tag:`chain-rule-forgot-inner-derivative`,feedback:`That is $2(x^3 - 2)$ at $x = 1$. Multiply by the derivative of the inner function, $3x^2$.`},{answer:1,tag:`evaluated-function-not-derivative`,feedback:`1 is $h(1)$, the value of the function. Differentiate first, then substitute.`}]},{id:`chain-rule-6`,level:3,kind:`numeric`,status:`unverified`,prompt:`Suppose $g(1) = 2$, $g'(1) = 3$ and $f'(2) = 5$. If $h(x) = f(g(x))$, what is $h'(1)$?`,answer:15,hint:`$h'(1) = f'(g(1)) \\cdot g'(1)$. Find $g(1)$ first.`,solution:`$h'(1) = f'(g(1)) \\cdot g'(1) = f'(2) \\cdot 3 = 5 \\cdot 3 = 15$.`,mistakes:[{answer:5,tag:`chain-rule-forgot-inner-derivative`,feedback:`That is $f'(g(1))$ alone. Multiply by the derivative of the inner function, $g'(1) = 3$.`},{answer:3,tag:`chain-rule-forgot-outer-derivative`,feedback:`That is $g'(1)$ alone. Multiply it by the outer derivative, $f'(g(1)) = f'(2) = 5$.`}]}]}]},n={id:`integrals`,courseId:`calculus-1`,courseTitle:`Calculus I`,title:`Integrals`,concepts:[{id:`antiderivatives`,title:`Antiderivatives and indefinite integrals`,objective:`Find antiderivatives of powers, constants, sine and cosine, and write them as indefinite integrals with + C.`,prerequisites:[],source:{title:`OpenStax Calculus Volume 1`,section:`4.10 Antiderivatives`,url:`https://openstax.org/books/calculus-volume-1/pages/4-10-antiderivatives`},status:`unverified`,explanation:[`A function $F$ is an antiderivative of $f$ when $F'(x) = f(x)$. Finding one runs differentiation backward.`,`Antiderivatives are never unique: if $F$ works, so does $F(x) + C$ for any constant $C$, because the derivative of a constant is 0. The indefinite integral $\\int f(x)\\,dx = F(x) + C$ names all of them at once.`,`The power rule runs backward: $\\int x^n\\,dx = \\frac{x^{n+1}}{n+1} + C$ for $n \\neq -1$. Raise the exponent by one, then divide by the new exponent. Also $\\int \\cos x\\,dx = \\sin x + C$ and $\\int \\sin x\\,dx = -\\cos x + C$.`,`Constant factors stay in front and sums are integrated term by term. You can always check an answer by differentiating it.`],takeaways:[`$\\int x^n\\,dx = \\frac{x^{n+1}}{n+1} + C$ for $n \\neq -1$`,`$\\int k\\,dx = kx + C$`,`$\\int \\cos x\\,dx = \\sin x + C$ and $\\int \\sin x\\,dx = -\\cos x + C$`,`Check an antiderivative by differentiating it.`],example:{problem:`Find $\\int (6x^2 - 4x + 3)\\,dx$.`,steps:[`Integrate term by term: $\\int 6x^2\\,dx = 6 \\cdot \\frac{x^3}{3} = 2x^3$, $\\int -4x\\,dx = -4 \\cdot \\frac{x^2}{2} = -2x^2$ and $\\int 3\\,dx = 3x$.`,`Add one constant for the whole answer: $2x^3 - 2x^2 + 3x + C$.`,`Check: $\\frac{d}{dx}(2x^3 - 2x^2 + 3x + C) = 6x^2 - 4x + 3$.`]},questions:[{id:`antiderivatives-1`,level:1,kind:`expression`,status:`unverified`,prompt:`Find $\\int x^2\\,dx$.`,answer:`x^3/3`,upToConstant:!0,antiderivativeOf:`x^2`,hint:`Raise the exponent by one, then divide by the new exponent.`,solution:`$\\int x^2\\,dx = \\frac{x^3}{3} + C$, since $\\frac{d}{dx}\\frac{x^3}{3} = x^2$.`,mistakes:[{answer:`x^3`,tag:`integral-power-rule-no-divide`,feedback:`The exponent is right, but the derivative of $x^3$ is $3x^2$. Divide by the new exponent: $\\frac{x^3}{3}$.`},{answer:`2x`,tag:`differentiated-instead`,feedback:`$2x$ is the derivative of $x^2$. Integration goes the other way: find a function whose derivative is $x^2$.`},{answer:`x^3/2`,tag:`integral-power-rule-wrong-divisor`,feedback:`Divide by the new exponent, 3, not the old one.`}]},{id:`antiderivatives-2`,level:1,kind:`expression`,status:`unverified`,prompt:`Find $\\int 5\\,dx$.`,answer:`5x`,upToConstant:!0,antiderivativeOf:`5`,hint:`Which function has a derivative of 5 everywhere?`,solution:`$\\int 5\\,dx = 5x + C$, since $\\frac{d}{dx}5x = 5$.`,mistakes:[{answer:`5`,tag:`integral-of-constant`,feedback:`A constant has derivative 0, not 5. The function with slope 5 everywhere is $5x$.`}]},{id:`antiderivatives-3`,level:1,kind:`expression`,status:`unverified`,prompt:`Find $\\int \\cos x\\,dx$.`,answer:`sin(x)`,upToConstant:!0,antiderivativeOf:`cos(x)`,hint:`Which trigonometric function has $\\cos x$ as its derivative?`,solution:`$\\int \\cos x\\,dx = \\sin x + C$, since $\\frac{d}{dx}\\sin x = \\cos x$.`,mistakes:[{answer:`-sin(x)`,tag:`trig-antiderivative-sign`,feedback:`$-\\sin x$ is the derivative of $\\cos x$. You need the function whose derivative is $\\cos x$, which is $\\sin x$.`}]},{id:`antiderivatives-4`,level:2,kind:`expression`,status:`unverified`,prompt:`Find $\\int (4x^3 + 6x - 2)\\,dx$.`,answer:`x^4 + 3x^2 - 2x`,upToConstant:!0,antiderivativeOf:`4x^3 + 6x - 2`,hint:`Integrate one term at a time, including the constant $-2$.`,solution:`Term by term: $x^4 + 3x^2 - 2x + C$.`,mistakes:[{answer:`12x^2 + 6`,tag:`differentiated-instead`,feedback:`That is the derivative. Integrate instead: raise each exponent by one and divide.`},{answer:`x^4 + 3x^2`,tag:`integral-of-constant`,feedback:`The constant term $-2$ integrates to $-2x$. It does not drop out the way it would in a derivative.`}]},{id:`antiderivatives-5`,level:2,kind:`expression`,status:`unverified`,prompt:`Find $\\int \\left(\\sqrt{x} + \\frac{1}{x^2}\\right)dx$.`,answer:`(2/3)x^(3/2) - 1/x`,upToConstant:!0,antiderivativeOf:`sqrt(x) + 1/x^2`,hint:`Rewrite both terms as powers first: $x^{1/2}$ and $x^{-2}$.`,solution:`$\\int x^{1/2}\\,dx = \\frac{x^{3/2}}{3/2} = \\frac{2}{3}x^{3/2}$ and $\\int x^{-2}\\,dx = \\frac{x^{-1}}{-1} = -\\frac{1}{x}$, so the answer is $\\frac{2}{3}x^{3/2} - \\frac{1}{x} + C$.`,mistakes:[{answer:`(2/3)x^(3/2) + 1/x`,tag:`integral-power-rule-negative-exponent`,feedback:`For $x^{-2}$ the new exponent is $-1$, and dividing by $-1$ makes the term negative: $-\\frac{1}{x}$.`},{answer:`(3/2)x^(3/2) - 1/x`,tag:`integral-power-rule-wrong-divisor`,feedback:`Dividing by $\\frac{3}{2}$ means multiplying by $\\frac{2}{3}$, so the first term is $\\frac{2}{3}x^{3/2}$.`}]},{id:`antiderivatives-6`,level:3,kind:`multiple-choice`,status:`unverified`,prompt:`Which of these is not an antiderivative of $2x$?`,solution:`$\\frac{d}{dx}(x+1)^2 = 2(x+1) = 2x + 2$, which is not $2x$. The other three differ from $x^2$ only by a constant, so each has derivative $2x$.`,options:[{text:`$x^2 + 7$`,tag:`antiderivative-constant-confusion`,feedback:`$x^2 + 7$ differs from $x^2$ by a constant, so its derivative is $2x$. It is an antiderivative.`},{text:`$x^2 - 100$`,tag:`antiderivative-constant-confusion`,feedback:`Subtracting a constant does not change the derivative, so $x^2 - 100$ is an antiderivative of $2x$.`},{text:`$(x + 1)^2$`,correct:!0},{text:`$x^2$`,tag:`antiderivative-constant-confusion`,feedback:`$\\frac{d}{dx}x^2 = 2x$, so $x^2$ is an antiderivative.`}]}]},{id:`riemann-sums`,title:`Areas and Riemann sums`,objective:`Estimate the area under a curve with left, right and midpoint rectangles.`,prerequisites:[],source:{title:`OpenStax Calculus Volume 1`,section:`5.1 Approximating Areas`,url:`https://openstax.org/books/calculus-volume-1/pages/5-1-approximating-areas`},status:`unverified`,explanation:[`To estimate the area under $f$ from $x = a$ to $x = b$, split the interval into $n$ equal pieces of width $\\Delta x = \\frac{b - a}{n}$ and stand a rectangle on each piece.`,`Each rectangle's height is $f$ at one point of its piece: the left endpoint, the right endpoint or the midpoint. The estimate is the sum of the areas, $\\sum f(x_i)\\,\\Delta x$, called a Riemann sum.`,`For an increasing function, left endpoints give rectangles that sit under the curve, so the left sum underestimates and the right sum overestimates. More rectangles give a better estimate.`],takeaways:[`$\\Delta x = \\frac{b - a}{n}$`,`Riemann sum: add $f(x_i)\\,\\Delta x$ over all $n$ rectangles.`,`Left endpoints run from $a$ to $b - \\Delta x$; right endpoints from $a + \\Delta x$ to $b$.`],example:{problem:`Estimate the area under $f(x) = x^2$ from 0 to 2 with 4 rectangles and right endpoints.`,steps:[`$\\Delta x = \\frac{2 - 0}{4} = 0.5$, so the right endpoints are $0.5, 1, 1.5, 2$.`,`The heights are $f(0.5) = 0.25$, $f(1) = 1$, $f(1.5) = 2.25$ and $f(2) = 4$, which add to $7.5$.`,`Multiply by the width: $7.5 \\times 0.5 = 3.75$.`]},questions:[{id:`riemann-sums-1`,level:1,kind:`numeric`,status:`unverified`,prompt:`The interval $[1, 7]$ is split into 3 equal pieces. What is $\\Delta x$?`,answer:2,hint:`Divide the length of the interval by the number of pieces.`,solution:`$\\Delta x = \\frac{7 - 1}{3} = 2$.`,mistakes:[{answer:6,tag:`riemann-width-not-divided`,feedback:`6 is the length of the whole interval. Divide it by the 3 pieces.`},{answer:2.3333,tag:`riemann-width-wrong-length`,feedback:`Use the length $7 - 1 = 6$, not 7.`}]},{id:`riemann-sums-2`,level:1,kind:`numeric`,status:`unverified`,prompt:`Estimate the area under $f(x) = 2x$ from 0 to 3 with 3 rectangles and left endpoints.`,answer:6,riemannSum:{of:`2x`,from:0,to:3,n:3,rule:`left`},hint:`$\\Delta x = 1$, and the left endpoints are 0, 1 and 2.`,solution:`Heights $f(0) = 0$, $f(1) = 2$, $f(2) = 4$, each times width 1: $0 + 2 + 4 = 6$.`,mistakes:[{answer:12,tag:`riemann-wrong-endpoints`,feedback:`12 uses the right endpoints 1, 2 and 3. Left endpoints start at 0.`},{answer:9,tag:`riemann-exact-area`,feedback:`9 is the exact area of the triangle. The question asks for the rectangle estimate.`}]},{id:`riemann-sums-3`,level:1,kind:`numeric`,status:`unverified`,prompt:`Estimate the area under $f(x) = x^2$ from 0 to 2 with 2 rectangles and midpoints.`,answer:2.5,riemannSum:{of:`x^2`,from:0,to:2,n:2,rule:`midpoint`},hint:`$\\Delta x = 1$, so the midpoints are 0.5 and 1.5.`,solution:`$f(0.5) = 0.25$ and $f(1.5) = 2.25$; times width 1 they add to $2.5$.`,mistakes:[{answer:5,tag:`riemann-wrong-endpoints`,feedback:`5 uses the right endpoints 1 and 2. Use the middle of each piece: 0.5 and 1.5.`},{answer:1,tag:`riemann-wrong-endpoints`,feedback:`1 uses the left endpoints 0 and 1. Use the middle of each piece: 0.5 and 1.5.`}]},{id:`riemann-sums-4`,level:2,kind:`numeric`,status:`unverified`,prompt:`Estimate the area under $f(x) = x^3$ from 0 to 2 with 4 rectangles and right endpoints.`,answer:6.25,riemannSum:{of:`x^3`,from:0,to:2,n:4,rule:`right`},hint:`$\\Delta x = 0.5$. Add $f(0.5) + f(1) + f(1.5) + f(2)$, then multiply by the width.`,solution:`$0.125 + 1 + 3.375 + 8 = 12.5$, and $12.5 \\times 0.5 = 6.25$.`,mistakes:[{answer:12.5,tag:`riemann-forgot-width`,feedback:`That is the sum of the heights. Multiply by the width $\\Delta x = 0.5$.`},{answer:2.25,tag:`riemann-wrong-endpoints`,feedback:`2.25 uses the left endpoints. Right endpoints are 0.5, 1, 1.5 and 2.`}]},{id:`riemann-sums-5`,level:2,kind:`numeric`,status:`unverified`,prompt:`Estimate the area under $f(x) = \\frac{1}{x}$ from 1 to 3 with 2 rectangles and left endpoints.`,answer:1.5,riemannSum:{of:`1/x`,from:1,to:3,n:2,rule:`left`},hint:`$\\Delta x = 1$, and the left endpoints are 1 and 2.`,solution:`$f(1) + f(2) = 1 + 0.5 = 1.5$, times width 1.`,mistakes:[{answer:.8333,tag:`riemann-wrong-endpoints`,feedback:`That uses the right endpoints 2 and 3. Left endpoints start at 1.`}]},{id:`riemann-sums-6`,level:3,kind:`multiple-choice`,status:`unverified`,prompt:`$f$ is increasing on $[a, b]$. How does the left Riemann sum compare with the true area under $f$?`,solution:`On each piece an increasing function is lowest at the left endpoint, so every left rectangle sits under the curve and the sum is too small.`,options:[{text:`It is smaller (an underestimate)`,correct:!0},{text:`It is larger (an overestimate)`,tag:`riemann-over-under`,feedback:`That is true of the right sum. On each piece an increasing function is lowest at the left end.`},{text:`It is exactly equal`,tag:`riemann-over-under`,feedback:`Rectangles match the curve exactly only for a constant function.`},{text:`It depends on the number of rectangles`,tag:`riemann-over-under`,feedback:`More rectangles make the error smaller, but every left rectangle still sits under an increasing curve.`}]}]},{id:`definite-integral`,title:`The definite integral`,objective:`Read a definite integral as net signed area and use its properties.`,prerequisites:[`riemann-sums`],source:{title:`OpenStax Calculus Volume 1`,section:`5.2 The Definite Integral`,url:`https://openstax.org/books/calculus-volume-1/pages/5-2-the-definite-integral`},status:`unverified`,explanation:[`As the number of rectangles grows without bound, Riemann sums approach one number: the definite integral $\\int_a^b f(x)\\,dx$.`,`It measures net signed area. Area above the $x$-axis counts as positive and area below counts as negative, so they can cancel.`,`Useful properties: $\\int_a^a f(x)\\,dx = 0$, reversing the limits flips the sign, $\\int_b^a f(x)\\,dx = -\\int_a^b f(x)\\,dx$, and intervals add: $\\int_a^b f(x)\\,dx + \\int_b^c f(x)\\,dx = \\int_a^c f(x)\\,dx$.`,`For simple shapes such as rectangles and triangles you can find the integral from geometry.`],takeaways:[`$\\int_a^b f(x)\\,dx$ is net signed area: above the axis minus below.`,`$\\int_b^a f(x)\\,dx = -\\int_a^b f(x)\\,dx$`,`$\\int_a^b f(x)\\,dx + \\int_b^c f(x)\\,dx = \\int_a^c f(x)\\,dx$`],example:{problem:`Find $\\int_0^4 2x\\,dx$ using geometry.`,steps:[`The region under $y = 2x$ from 0 to 4 is a triangle with base 4 and height $2 \\cdot 4 = 8$.`,`Its area is $\\frac{1}{2} \\cdot 4 \\cdot 8 = 16$, and it lies above the axis, so $\\int_0^4 2x\\,dx = 16$.`]},questions:[{id:`definite-integral-1`,level:1,kind:`numeric`,status:`unverified`,prompt:`Find $\\int_0^3 4\\,dx$.`,answer:12,integral:{of:`4`,from:0,to:3},hint:`The region is a rectangle. What are its height and width?`,solution:`A rectangle of height 4 and width 3 has area 12.`,mistakes:[{answer:4,tag:`definite-integral-height-only`,feedback:`4 is the height. Multiply by the width, $3 - 0 = 3$.`}]},{id:`definite-integral-2`,level:1,kind:`numeric`,status:`unverified`,prompt:`Find $\\int_0^2 x\\,dx$.`,answer:2,integral:{of:`x`,from:0,to:2},hint:`The region is a triangle with base 2 and height 2.`,solution:`$\\frac{1}{2} \\cdot 2 \\cdot 2 = 2$.`,mistakes:[{answer:4,tag:`triangle-area-no-half`,feedback:`4 is the area of the full square. The region is a triangle, so take half.`}]},{id:`definite-integral-3`,level:1,kind:`numeric`,status:`unverified`,prompt:`If $\\int_1^5 f(x)\\,dx = 8$, what is $\\int_5^1 f(x)\\,dx$?`,answer:-8,hint:`What happens to a definite integral when the limits are swapped?`,solution:`Reversing the limits flips the sign: $\\int_5^1 f(x)\\,dx = -8$.`,mistakes:[{answer:8,tag:`reversed-limits-sign`,feedback:`Swapping the limits changes the sign of the integral.`}]},{id:`definite-integral-4`,level:2,kind:`numeric`,status:`unverified`,prompt:`If $\\int_0^6 f(x)\\,dx = 10$ and $\\int_0^2 f(x)\\,dx = 3$, find $\\int_2^6 f(x)\\,dx$.`,answer:7,hint:`The integral from 0 to 6 is the integral from 0 to 2 plus the integral from 2 to 6.`,solution:`$10 = 3 + \\int_2^6 f(x)\\,dx$, so $\\int_2^6 f(x)\\,dx = 7$.`,mistakes:[{answer:13,tag:`interval-additivity`,feedback:`The two smaller intervals add up to the larger one, so subtract: $10 - 3$.`}]},{id:`definite-integral-5`,level:2,kind:`numeric`,status:`unverified`,prompt:`Find $\\int_{-2}^{2} x\\,dx$.`,answer:0,integral:{of:`x`,from:-2,to:2},hint:`Sketch $y = x$. Which part is above the axis and which is below?`,solution:`The triangle from 0 to 2 has area 2 above the axis and the one from $-2$ to 0 has area 2 below, so they cancel: 0.`,mistakes:[{answer:4,tag:`signed-area`,feedback:`4 is the total area. Area below the axis counts as negative in a definite integral.`}]},{id:`definite-integral-6`,level:3,kind:`multiple-choice`,status:`unverified`,prompt:`A car's velocity $v(t)$ is negative for part of the time from $t = 0$ to $t = 10$. What does $\\int_0^{10} v(t)\\,dt$ give?`,solution:`Time below the axis counts negatively, so the integral gives the net change in position: the displacement.`,options:[{text:`The displacement (net change in position)`,correct:!0},{text:`The total distance traveled`,tag:`signed-area`,feedback:`Total distance counts backward motion as positive. The integral counts it as negative, so it gives displacement.`},{text:`The average velocity`,tag:`definite-integral-meaning`,feedback:`Average velocity is the integral divided by the time, 10.`},{text:`The velocity at $t = 10$`,tag:`definite-integral-meaning`,feedback:`The integral adds up velocity times time over the whole interval; it is not a single value of $v$.`}]}]},{id:`fundamental-theorem`,title:`The Fundamental Theorem of Calculus`,objective:`Evaluate definite integrals with antiderivatives, and differentiate an integral with a variable limit.`,prerequisites:[`antiderivatives`,`definite-integral`],source:{title:`OpenStax Calculus Volume 1`,section:`5.3 The Fundamental Theorem of Calculus`,url:`https://openstax.org/books/calculus-volume-1/pages/5-3-the-fundamental-theorem-of-calculus`},status:`unverified`,explanation:[`Part 1: if $F(x) = \\int_a^x f(t)\\,dt$, then $F'(x) = f(x)$. Differentiating an integral with respect to its upper limit gives back the integrand at that limit.`,`When the upper limit is a function $g(x)$, the chain rule adds a factor: $\\frac{d}{dx}\\int_a^{g(x)} f(t)\\,dt = f(g(x))\\,g'(x)$. The lower limit is a constant, so it contributes nothing.`,`Part 2: if $F$ is any antiderivative of $f$, then $\\int_a^b f(x)\\,dx = F(b) - F(a)$. This replaces the limit of Riemann sums with a subtraction.`,`The $+ C$ cancels in $F(b) - F(a)$, so it is left out of definite integrals.`],takeaways:[`$\\frac{d}{dx}\\int_a^x f(t)\\,dt = f(x)$`,`$\\frac{d}{dx}\\int_a^{g(x)} f(t)\\,dt = f(g(x))\\,g'(x)$`,`$\\int_a^b f(x)\\,dx = F(b) - F(a)$ for any antiderivative $F$`],example:{problem:`Evaluate $\\int_1^3 x^2\\,dx$.`,steps:[`An antiderivative of $x^2$ is $F(x) = \\frac{x^3}{3}$.`,`$F(3) - F(1) = \\frac{27}{3} - \\frac{1}{3} = \\frac{26}{3}$.`]},questions:[{id:`fundamental-theorem-1`,level:1,kind:`numeric`,status:`unverified`,prompt:`Evaluate $\\int_0^2 3x^2\\,dx$.`,answer:8,integral:{of:`3x^2`,from:0,to:2},hint:`An antiderivative of $3x^2$ is $x^3$. Compute $F(2) - F(0)$.`,solution:`$F(x) = x^3$, so $F(2) - F(0) = 8 - 0 = 8$.`,mistakes:[{answer:12,tag:`evaluated-integrand`,feedback:`12 is the integrand at $x = 2$. Find an antiderivative first, then subtract its values.`}]},{id:`fundamental-theorem-2`,level:1,kind:`expression`,status:`unverified`,prompt:`Find $\\frac{d}{dx}\\int_1^x \\sqrt{1 + t^2}\\,dt$.`,answer:`sqrt(1 + x^2)`,ftcOf:{integrand:`sqrt(1 + x^2)`,lower:1,upper:`x`},hint:`Part 1 of the theorem: put the upper limit into the integrand.`,solution:`By Part 1, the derivative is the integrand at the upper limit: $\\sqrt{1 + x^2}$.`,mistakes:[{answer:`sqrt(1 + x^2) - sqrt(2)`,tag:`ftc-lower-limit`,feedback:`The lower limit is a constant, so it adds nothing to the derivative. The answer is just $\\sqrt{1 + x^2}$.`},{answer:`x/sqrt(1 + x^2)`,tag:`ftc-differentiated-integrand`,feedback:`That is the derivative of $\\sqrt{1 + x^2}$. Part 1 says the derivative of the integral is the integrand itself.`}]},{id:`fundamental-theorem-3`,level:1,kind:`numeric`,status:`unverified`,prompt:`Evaluate $\\int_0^{\\pi/2} \\cos x\\,dx$.`,answer:1,integral:{of:`cos(x)`,from:0,to:1.5707963267948966},hint:`An antiderivative of $\\cos x$ is $\\sin x$.`,solution:`$\\sin\\frac{\\pi}{2} - \\sin 0 = 1 - 0 = 1$.`,mistakes:[{answer:-1,tag:`trig-antiderivative-sign`,feedback:`The antiderivative of $\\cos x$ is $\\sin x$, not $-\\sin x$.`}]},{id:`fundamental-theorem-4`,level:2,kind:`numeric`,status:`unverified`,prompt:`Evaluate $\\int_1^4 (2x + 1)\\,dx$.`,answer:18,integral:{of:`2x + 1`,from:1,to:4},hint:`Use $F(x) = x^2 + x$ and compute $F(4) - F(1)$.`,solution:`$F(4) - F(1) = (16 + 4) - (1 + 1) = 20 - 2 = 18$.`,mistakes:[{answer:20,tag:`ftc-forgot-lower-limit`,feedback:`20 is $F(4)$. Subtract $F(1) = 2$ as well.`},{answer:22,tag:`ftc-added-limits`,feedback:`Subtract $F(1)$ from $F(4)$ instead of adding it.`}]},{id:`fundamental-theorem-5`,level:2,kind:`expression`,status:`unverified`,prompt:`Find $\\frac{d}{dx}\\int_0^{x^2} \\cos t\\,dt$.`,answer:`2x*cos(x^2)`,ftcOf:{integrand:`cos(x)`,lower:0,upper:`x^2`},hint:`The upper limit is $x^2$, so the chain rule adds a factor of its derivative.`,solution:`$\\cos(x^2) \\cdot \\frac{d}{dx}x^2 = 2x\\cos(x^2)$.`,mistakes:[{answer:`cos(x^2)`,tag:`ftc-forgot-chain-rule`,feedback:`The upper limit is $x^2$, not $x$, so multiply by its derivative $2x$.`},{answer:`sin(x^2)`,tag:`ftc-evaluated-integral`,feedback:`$\\sin(x^2)$ is the integral itself. The question asks for its derivative.`}]},{id:`fundamental-theorem-6`,level:3,kind:`multiple-choice`,status:`unverified`,prompt:`Why is $+ C$ left out when evaluating $\\int_a^b f(x)\\,dx = F(b) - F(a)$?`,solution:`$(F(b) + C) - (F(a) + C) = F(b) - F(a)$: the constant cancels, so any antiderivative gives the same number.`,options:[{text:`It cancels in the subtraction`,correct:!0},{text:`$C$ is always 0`,tag:`constant-of-integration`,feedback:`$C$ can be any constant. It is left out because it cancels, not because it is 0.`},{text:`Definite integrals have no antiderivative`,tag:`constant-of-integration`,feedback:`Part 2 uses an antiderivative $F$. The point is that every choice of $F$ gives the same answer.`},{text:`It is added after subtracting`,tag:`constant-of-integration`,feedback:`A definite integral is a number, so no constant is added at all.`}]}]},{id:`substitution`,title:`Substitution`,objective:`Integrate a composite function by substituting u for its inside part.`,prerequisites:[`antiderivatives`,`fundamental-theorem`],source:{title:`OpenStax Calculus Volume 1`,section:`5.5 Substitution`,url:`https://openstax.org/books/calculus-volume-1/pages/5-5-substitution`},status:`unverified`,explanation:[`Substitution undoes the chain rule. When an integrand has the form $f(g(x))\\,g'(x)$, set $u = g(x)$, so $du = g'(x)\\,dx$, and the integral becomes $\\int f(u)\\,du$.`,`Choose $u$ as the inside of a composite function whose derivative, up to a constant factor, also appears. If the factor is off by a constant, divide by it.`,`After integrating in $u$, put $g(x)$ back in for $u$. For a definite integral, change the limits to $u$-values instead, and there is nothing to put back.`],takeaways:[`$\\int f(g(x))\\,g'(x)\\,dx = \\int f(u)\\,du$ with $u = g(x)$`,`Pick $u$ so that $du$, up to a constant, is already in the integrand.`,`Definite integrals: change the limits to $u = g(a)$ and $u = g(b)$.`],example:{problem:`Find $\\int 2x(x^2 + 1)^3\\,dx$.`,steps:[`Let $u = x^2 + 1$, so $du = 2x\\,dx$.`,`The integral becomes $\\int u^3\\,du = \\frac{u^4}{4} + C$.`,`Substitute back: $\\frac{(x^2 + 1)^4}{4} + C$.`]},questions:[{id:`substitution-1`,level:1,kind:`multiple-choice`,status:`unverified`,prompt:`To find $\\int 3x^2 \\cos(x^3)\\,dx$, which substitution works?`,solution:`With $u = x^3$, $du = 3x^2\\,dx$ is already in the integrand, leaving $\\int \\cos u\\,du$.`,options:[{text:`$u = x^3$`,correct:!0},{text:`$u = \\cos(x^3)$`,tag:`substitution-choice`,feedback:`Then $du = -3x^2\\sin(x^3)\\,dx$, which is not in the integrand. Choose the inside of the composite function.`},{text:`$u = 3x^2$`,tag:`substitution-choice`,feedback:`$3x^2$ is the factor that becomes $du$. Choose the inside of $\\cos$, whose derivative it is.`},{text:`$u = x$`,tag:`substitution-choice`,feedback:`That changes nothing. Choose the inside of the composite function, $x^3$.`}]},{id:`substitution-2`,level:1,kind:`expression`,status:`unverified`,prompt:`Find $\\int 2x(x^2 + 3)^4\\,dx$.`,answer:`(x^2 + 3)^5/5`,upToConstant:!0,antiderivativeOf:`2x(x^2 + 3)^4`,hint:`Let $u = x^2 + 3$. Then $du = 2x\\,dx$.`,solution:`With $u = x^2 + 3$: $\\int u^4\\,du = \\frac{u^5}{5} + C = \\frac{(x^2 + 3)^5}{5} + C$.`,mistakes:[{answer:`(x^2 + 3)^5`,tag:`integral-power-rule-no-divide`,feedback:`After substituting, $\\int u^4\\,du = \\frac{u^5}{5}$. Divide by the new exponent.`}]},{id:`substitution-3`,level:1,kind:`expression`,status:`unverified`,prompt:`Find $\\int \\cos(5x)\\,dx$.`,answer:`sin(5x)/5`,upToConstant:!0,antiderivativeOf:`cos(5x)`,hint:`Let $u = 5x$, so $dx = \\frac{du}{5}$.`,solution:`$\\frac{1}{5}\\int \\cos u\\,du = \\frac{\\sin(5x)}{5} + C$. Check: $\\frac{d}{dx}\\frac{\\sin(5x)}{5} = \\cos(5x)$.`,mistakes:[{answer:`sin(5x)`,tag:`substitution-missing-factor`,feedback:`The derivative of $\\sin(5x)$ is $5\\cos(5x)$, which is 5 times too big. Divide by 5.`},{answer:`5sin(5x)`,tag:`substitution-factor-inverted`,feedback:`Since $du = 5\\,dx$, you divide by 5, not multiply.`}]},{id:`substitution-4`,level:2,kind:`expression`,status:`unverified`,prompt:`Find $\\int \\frac{x}{x^2 + 1}\\,dx$.`,answer:`ln(x^2 + 1)/2`,upToConstant:!0,antiderivativeOf:`x/(x^2 + 1)`,hint:`Let $u = x^2 + 1$. Then $du = 2x\\,dx$, so $x\\,dx = \\frac{du}{2}$. Recall $\\int \\frac{1}{u}\\,du = \\ln|u| + C$.`,solution:`$\\frac{1}{2}\\int \\frac{1}{u}\\,du = \\frac{1}{2}\\ln(x^2 + 1) + C$. No absolute value is needed, since $x^2 + 1 > 0$.`,mistakes:[{answer:`ln(x^2 + 1)`,tag:`substitution-missing-factor`,feedback:`The derivative of $\\ln(x^2 + 1)$ is $\\frac{2x}{x^2 + 1}$, twice the integrand. Divide by 2.`},{answer:`2ln(x^2 + 1)`,tag:`substitution-factor-inverted`,feedback:`Since $x\\,dx = \\frac{du}{2}$, the factor is $\\frac{1}{2}$, not 2.`}]},{id:`substitution-5`,level:2,kind:`numeric`,status:`unverified`,prompt:`Evaluate $\\int_0^1 2x(x^2 + 1)^3\\,dx$.`,answer:3.75,integral:{of:`2x(x^2 + 1)^3`,from:0,to:1},hint:`With $u = x^2 + 1$, the limits change: $x = 0$ gives $u = 1$ and $x = 1$ gives $u = 2$.`,solution:`$\\int_1^2 u^3\\,du = \\frac{2^4}{4} - \\frac{1^4}{4} = 4 - \\frac{1}{4} = 3.75$.`,mistakes:[{answer:.25,tag:`substitution-limits-not-changed`,feedback:`That keeps the $x$-limits 0 and 1 for $u$. Change them: $u$ runs from 1 to 2.`},{answer:4,tag:`ftc-forgot-lower-limit`,feedback:`4 is the value at the upper limit $u = 2$. Subtract the value at $u = 1$, which is $\\frac{1}{4}$.`}]},{id:`substitution-6`,level:3,kind:`multiple-choice`,status:`unverified`,prompt:`In $\\int_0^2 x\\,e^{x^2}\\,dx$ you substitute $u = x^2$. What are the new limits?`,solution:`The limits are $x$-values, so convert each one: $u = 0^2 = 0$ and $u = 2^2 = 4$.`,options:[{text:`$u$ from 0 to 4`,correct:!0},{text:`$u$ from 0 to 2`,tag:`substitution-limits-not-changed`,feedback:`0 and 2 are the $x$-limits. Put each into $u = x^2$.`},{text:`$u$ from 1 to $e^4$`,tag:`substitution-limits-wrong-function`,feedback:`The limits come from $u = x^2$, not from $e^{x^2}$.`},{text:`The limits stay the same`,tag:`substitution-limits-not-changed`,feedback:`The integral is now in terms of $u$, so the limits must be $u$-values.`}]}]}]},r={1:`Check`,2:`Apply`,3:`Concept`},i=t,a=n,o=[i,a];function s(e){for(let t of o){let n=t.concepts.find(t=>t.id===e);if(n)return{unit:t,concept:n}}}function c(e,t){return e.questions.filter(e=>e.level===t)}function l(e){return e.status!==`verified`||e.questions.some(e=>e.status!==`verified`)}var u=e();function d(){return(0,u.jsx)(`span`,{className:`unreviewed-label`,children:`Not yet reviewed`})}export{l as a,s as i,r as n,a as o,i as r,c as s,d as t};